package com.grievancecampus.servlet;
import javax.servlet.http.*;import java.io.*;import java.nio.file.*;import java.sql.*;import com.dao.DBConnection;import com.grievancecampus.model.User;
/** Streams a stored image only to its owner, an assigned staff member, or an administrator. */
public class PhotoServlet extends HttpServlet {
 protected void doGet(HttpServletRequest request,HttpServletResponse response)throws IOException{
  User user=(User)request.getSession().getAttribute("user");long id;try{id=Long.parseLong(request.getParameter("id"));}catch(Exception e){response.sendError(400);return;}
  String sql="SELECT g.photo_path,g.student_id,g.department,g.section,EXISTS(SELECT 1 FROM gc_assignments a WHERE a.grievance_id=g.grievance_id AND a.assignee_id=?) assigned FROM gc_grievances g WHERE g.grievance_id=? AND g.deleted_at IS NULL";
  try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setLong(1,user.getId());p.setLong(2,id);try(ResultSet r=p.executeQuery()){if(!r.next()){response.sendError(404);return;}String role=user.getRole();boolean permitted="ADMIN".equals(role)||r.getLong("student_id")==user.getId()||r.getBoolean("assigned")||"HOD".equals(role)&&user.getDepartment()!=null&&user.getDepartment().equals(r.getString("department"))||("TEACHER".equals(role)||"CLASS_TEACHER".equals(role))&&user.getDepartment()!=null&&user.getDepartment().equals(r.getString("department"))&&java.util.Objects.equals(user.getSection(),r.getString("section"));if(!permitted){response.sendError(403);return;}String name=r.getString("photo_path");if(name==null||!name.matches("[a-f0-9-]{36}\\.(jpg|png|webp)")){response.sendError(404);return;}Path dir=uploadDirectory(),file=dir.resolve(name).normalize();if(!dir.equals(file.getParent())||!Files.isRegularFile(file)){response.sendError(404);return;}String type=name.endsWith(".jpg")?"image/jpeg":name.endsWith(".png")?"image/png":"image/webp";response.setContentType(type);response.setHeader("X-Content-Type-Options","nosniff");response.setHeader("Cache-Control","private, no-store");try(InputStream in=Files.newInputStream(file);OutputStream out=response.getOutputStream()){in.transferTo(out);}}}
  catch(SQLException e){getServletContext().log("Photo lookup failed",e);response.sendError(500);}
 }
 private Path uploadDirectory()throws IOException{String configured=System.getenv("GC_UPLOAD_DIR");Path dir=configured==null||configured.isBlank()?Paths.get(System.getProperty("catalina.base","."),"grievance-uploads"):Paths.get(configured);Files.createDirectories(dir);return dir.toRealPath();}
}
